def is_dag(edges):
    in_degree = [0] * (N + 1)
    for edge in edges:
        for i in edge:
            if i != '0':
                in_degree[int(i)] += 1

    queue, add_edges = deque(), 0

    # Add nodes with in-degree 0 to the queue
    for i in range(1, N + 1):
        if in_degree[i] == 0:
            queue.append(i)

    while queue:
        node = queue.popleft()
        add_edges += 1
        for i in range(N):
            if edges[i][node] == '1' and in_degree[i] > 0 and in_degree[i] > in_degree[node]:
                queue.append(i)
                del in_degree[i]
            elif edges[i][node] == '1' and in_degree[i] > 0 and in_degree[i] <= in_degree[node]:
                in_degree[i] -= 1

    return add_edges == N

