from functools import lru_cache

def max_bitwise_and_sum(ages):
    n = len(ages)
    left = [ages for _ in range(n)]
    right = [ages for _ in range(n)]

    # Precompute XOR of subarrays for faster lookup
    for i in range(n):
        left[i] = ages[i] ^ left[i - 1] if i > 0 else ages[i]
    for i in range(n - 1, -1, -1):
        right[i] = ages[i] ^ right[i + 1] if i < n - 1 else ages[i]

    @lru_cache(None)
    def dp(index):
        if index == n:
            return 0
        max_gain = ages[index]
        for friend in range(n):
            if friend != index and left[index] & left[friend] == 0:
                max_gain = max(max_gain, [dp(j) for j in range(n) if j != index and j != friend][
                               (index ^ friend) & 1] + ages[index])
        return max_gain

    return max(ages) + dp(0)

