from collections import defaultdict
from typing import List

def maximize_edges(graph: List[List[int]]) -> int:
    vertices = len(graph)
    edges_added = 0
    edges = []

    while not is_dag(graph, 0):
        for v in range(1, vertices):
            if graph[v][0] == 1:
                graph[v][0] = 0
                edges.append((0, v))
                edges_added += 1
                break
        else:
            break

        for v in range(1, vertices):
            if graph[v][1] == 1:
                graph[v][1] = 0
                edges.append((1, v))
                edges_added += 1
                break
        else:
            break

        for v in range(1, vertices):
            if graph[v][2] == 1:
                graph[v][2] = 0
                edges.append((2, v))
                edges_added += 1
                break
        else:
            break

    return edges_added

def is_dag(graph: List[List[int]], root: int) -> bool:
    visited = [False] * len(graph)
    queue = [root]

    visited[root] = True

    while queue:
        v = queue.pop(0)
        for w in range(len(graph)):
            if graph[v][w] == 1 and not visited[w]:
                visited[w] = True
                queue.append(w)

    return False in visited

