import sys
from typing import List

def max_edges_non_cycle(vertices: int) -> int:
    if vertices == 1:
        return 0

    # Build the adjacency matrix
    adjacency_matrix = []
    for i in range(vertices):
        adjacency_matrix.append([0]*vertices)

    # Populate the adjacency matrix based on input
    for line in sys.stdin:
        row = list(map(int, line.strip()))
        adjacency_matrix[row[0]-1] = row

    # Convert the adjacency matrix to an adjacency list
    adjacency_list = [[] for _ in range(vertices)]
    for i in range(vertices):
        for j in range(vertices):
            if adjacency_matrix[i][j] == 1:
                adjacency_list[i].append(j)

    # Function to convert a graph to an array of edges
    def to_edges(graph: List[List[int]]) -> List[List[int]]:
        edges = []
        for from_vertice in range(len(graph)):
            for to_vertice in graph[from_vertice]:
                if (from_vertice, to_vertice) not in edges and (to_vertice, from_vertice) not in edges:
                    edges.append((from_vertice + 1, to_vertice + 1))
        return edges

    # Transpose the adjacency matrix to reuse it
    transpose = [[0]*vertices for _ in range(vertices)]
    for i in range(vertices):
        for j in range(vertices):
            transpose[i][j] = adjacency_matrix[j][i]

    # Convert the adjacency matrix to adjacency list
    for i in range(len(transpose)):
        for j in range(len(transpose[0])):
            if transpose[i][j] == 1:
                adjacency_list[i].append(j)
                adjacency_list[j].append(i)

    # Get the edges in either direction
    positive_edges = to_edges(adjacency_list)
    negative_edges = to_edges(transpose[:(vertices)//2])
    negative_edges.extend(to_edges(transpose[(vertices)//2+1:]))

    # Create a list to hold the final edges
    final_edges = []

    # Use the larger of the two lists to pair edges
    for edge in positive_edges if len(positive_edges) > len(negative_edges) else negative_edges:
        final_edges.extend(edge)

    # Ensure there are no duplicates in the final edges list
    final_edges = list(set(final_edges))

    # Sort the final edges
    final_edges.sort()

    # Output the number of edges and the edges themselves
    print(len(final_edges))
    for edge in final_edges:
        print(*edge)

