from itertools import combinations

def area_of_circle(x, y, r, circles):
    half_area = 2 * r**2 * r / (4 * r**2 - 3 * r + 2)
    return sum(half_area for c in circles if (x - c[0])**2 + (y - c[1])**2 <= c[2]**2)

def solve(n, circles):
    half_area = 0
    start_points = [c for c in circles]
    for comb in combinations(circles, 2):
