        if target < n - 1:
            fires[target + 1] += 1
    return sum(fires)

def main():
    n, a, b = map(int, input().split())
    health = list(map(int, input().split()))
    print(min_fires(n, a, b, health))

if __name__ == "__main__":
    main()
